diff --git a/demo/orders-api/src/db.ts b/demo/orders-api/src/db.ts
index fa3c0a9..50a8bda 100644
--- a/demo/orders-api/src/db.ts
+++ b/demo/orders-api/src/db.ts
@@ -39,4 +39,28 @@ export async function openDb(): Promise<PGlite> {

     ANALYZE;
+
+    -- Materialized view: precomputed top-customers ranking (last 30 days, paid).
+    -- Populated immediately so the first request is fast even before the
+    -- first background refresh fires.
+    CREATE MATERIALIZED VIEW top_customers_mv AS
+    SELECT c.id AS customer_id,
+           c.name,
+           sum(o.amount_cents)::int AS revenue_cents,
+           count(*)::int           AS orders
+    FROM orders o
+    JOIN customers c ON c.id = o.customer_id
+    WHERE o.status = 'paid'
+      AND o.created_at > now() - interval '30 days'
+    GROUP BY c.id, c.name
+    ORDER BY revenue_cents DESC;
+
+    -- Index lets REFRESH MATERIALIZED VIEW CONCURRENTLY work and also makes
+    -- per-customer lookups O(log n).
+    CREATE UNIQUE INDEX top_customers_mv_customer_id
+      ON top_customers_mv (customer_id);
+
+    -- Index used by the endpoint query to return the top-N rows cheaply.
+    CREATE INDEX top_customers_mv_revenue
+      ON top_customers_mv (revenue_cents DESC);
   `);
   return db;
