+// Refreshes the materialized view every intervalMs milliseconds using
+// CONCURRENT refresh so readers are never blocked.  Returns a stop function
+// that cancels the next scheduled refresh and resolves when any in-flight
+// refresh has finished — useful in tests and graceful-shutdown handlers.
+export function startMatviewRefresh(db: PGlite, intervalMs = 5_000): () => Promise<void> {
+  let stopped = false;
+  // Track the in-flight refresh promise so stop() can await it.
+  let inFlight: Promise<void> = Promise.resolve();
+
+  const schedule = (): void => {
+    if (stopped) return;
+    inFlight = db
+      .exec("REFRESH MATERIALIZED VIEW CONCURRENTLY top_customers_mv")
+      .then(() => {
+        if (!stopped) setTimeout(schedule, intervalMs);
+      })
+      .catch((err) => {
+        // Log but do not crash the server — stale data is better than no data.
+        console.error("matview refresh failed:", err);
+        if (!stopped) setTimeout(schedule, intervalMs);
+      });
+  };
+
+  setTimeout(schedule, intervalMs);
+
+  return () => {
+    stopped = true;
+    return inFlight;
+  };
+}
